class InvalidTransitionError(Exception): pass

class ProtocolFSM:
    def __init__(self, initial_state: str = "INIT"):
        self.state = initial_state
        self.history = [initial_state]
        self._transitions = {
            "INIT": ["PREPARE"],
            "PREPARE": ["COMMIT", "ABORT"],
            "COMMIT": ["DONE"],
            "ABORT": ["DONE"]
        }

    def transition(self, to_state: str):
        if to_state not in self._transitions.get(self.state, []):
            raise InvalidTransitionError(f"Cannot transition from {self.state} to {to_state}")
        self.state = to_state
        self.history.append(to_state)
